<script lang="ts">
  import { onMount } from 'svelte';
  import Graph from './Graph.svelte';
 import Traces from './Traces.svelte';
 import {contextualMapping} from './trace';
 let explorationMode=$state('trace');
  import Modal from './Modal.svelte';
  import FieldHelp from './FieldHelp.svelte';
  import Timeline from './Timeline.svelte';
  import Errors from './Errors.svelte';
  import Invitations from './Invitations.svelte';
  import { invitationLocation } from './invitation';
  import type {TimelineData} from './timeline';
  import { errorEvidence } from './graphEvidence';
  import { editEventDefinition, captureReferenceBounds, referenceBound, removeEventMapping } from './workspace';
  import { edgeKey, transitions, lensEvidence, type Layout, type Lens } from './graph';
  import { acceptsSnapshot, dateTime, duration, isoLocal, histogramQuantile, mergeSummaryGroups, discoveryChoices, evidenceCopy, receiptLagMilliseconds } from './helpers';
  import { translate, type Language } from './i18n';
  import type { Snapshot, Definition, Mapping, SavedView, Model, Journey, Evidence } from './types';
  let language = $state<Language>('en');
  const t = (key:string)=>translate(key,language);
  let authenticated=$state(false), passphrase=$state(''), csrf=$state(''), busy=$state(false), loading=$state(false);
  let role=$state<'owner'|'viewer'>('owner'), accessExpires=$state(''), invitationToken=$state(''), invitationEnded=$state(false);
  let readOnly=$derived(role==='viewer');
  let sessionCheck=false,sessionReady=$state(false);
  let error=$state(''), notice=$state(''), snapshot=$state<Snapshot|null>(null);
  let tab=$state('explore'), mode=$state('historical'), paused=$state(false), baseline=$state(false), connection=$state('Historical snapshot');
  let from=$state(new Date(Date.now()-7*86400000).toISOString().slice(0,16)), to=$state(''), version=$state(''), definition=$state(''), scope=$state('');
  let liveStart=$state(''), selectedStep=$state(''), selectedReference=$state<SavedView|null>(null), endpointStart=$state('first'), endpointEnd=$state('last');
  let draft=$state<Definition>({version:0,goal:'',mappings:[],fallbackTiming:false}), preview=$state<any>(null), draftLoaded=false;
  let pendingReferenceDelete=$state<number|null>(null);
  let viewName=$state(''),viewMode=$state('goal-backward'), viewStart=$state(''),viewEnd=$state('');
  let deleteScope=$state(''),deleteConfirm=$state(''),summaryBucket=$state(''),pendingDelete=$state<'visit'|'app'|'bucket'|null>(null), copied=$state('');
  let pageLimits=$state<Record<string,number>>({});
  let timelineWindow=$state('24h'), timelineData=$state<TimelineData|null>(null), timelineLoading=$state(false), timelineError=$state('');
  let timelineGeneration=0;
  $effect(()=>{if(tool==='filters'&&authenticated)void refreshTimeline(timelineWindow,scope,version,definition)});
  async function refreshTimeline(window:string,visit:string,appVersion:string,configVersion:string){const generation=++timelineGeneration;timelineLoading=true;timelineError='';const q=new URLSearchParams({window});if(visit)q.set('scope',visit);if(appVersion)q.set('version',appVersion);if(configVersion)q.set('definition',configVersion);try{const result=await api('timeline?'+q);if(generation===timelineGeneration)timelineData=result}catch(e){if(generation===timelineGeneration){timelineData=null;timelineError=e instanceof Error?e.message:'Timeline unavailable'}}finally{if(generation===timelineGeneration)timelineLoading=false}}
  async function readErrors(search:string,currentView:boolean){const q=new URLSearchParams();if(search)q.set('q',search);if(currentView){if(from&&mode==='historical')q.set('from',isoLocal(from));if(to&&mode==='historical')q.set('to',isoLocal(to));if(scope)q.set('scope',scope);if(version)q.set('version',version);if(definition)q.set('definition',definition);if(mode==='live'&&liveStart)q.set('from',liveStart)}return api('errors?'+q)}
  function exploreError(event:Evidence){scope=event.scope;mode='historical';from=new Date(Date.now()-30*86400000).toISOString().slice(0,16);to='';selectedReference=null;exploration=null;selectedStep='';selectedEdge='';applyFilters();tool='evidence'}
  function chooseTimeRange(start:string,end:string){from=start.replace(/Z$/,'');to=end.replace(/Z$/,'');applyFilters()}
  function recentRange(hours:number){timelineWindow=hours<=1?'1h':hours<=24?'24h':'7d';const now=Date.now();chooseTimeRange(new Date(now-hours*3600000).toISOString(),new Date(now).toISOString())}
  let exploration=$state<{mode:string;start:string;end:string}|null>(null);
  let layout=$state<Layout>('hierarchy'), lens=$state<Lens>('none');
  let tool=$state(''), menuOpen=$state(false), showDiscovery=$state(false), selectedEdge=$state('');
  let edgeFrom=$state(''), edgeTo=$state(''), mappingOpen=$state(false), mappingIndex=$state(-1), makeGoal=$state(false);
  let eventDraft=$state<Mapping>({event:'',step:'',source:'',kind:'step',key:'',value:''});
  let unmapEvent=$state(false);
  let mappingPreview=$state<any>(null), segmentStart=$state('');
  function chooseNode(id:string){if(tool==='table')tool='';selectedStep=id;selectedEdge='';if(segmentStart&&id){viewStart=segmentStart;viewEnd=eventForStage(id);viewMode='segment';viewName='';segmentStart='';exploreReference('segment',viewStart,viewEnd)}}
  function chooseEdge(a:string,b:string){edgeFrom=a;edgeTo=b;selectedEdge=edgeKey(a,b);selectedStep=''}
  function eventForStage(id:string){return id.startsWith('event:')?id.slice(6):(active?.mappings.find(m=>m.step===id)?.event??id)}
  function openMapping(event:string,goal=false){if(readOnly)return;const source=active??draft;mappingIndex=source.mappings.findIndex(m=>m.event===event);eventDraft=mappingIndex>=0?{...source.mappings[mappingIndex]}:{event,step:event,source:'',kind:'step',key:'',value:''};makeGoal=goal;unmapEvent=false;mappingPreview=null;mappingOpen=true;tool='';error=''}
  function openEvidenceMapping(e:Evidence,suggestion?:string){if(readOnly)return;const mapping=contextualMapping(e,suggestion);const source=active??draft;mappingIndex=source.mappings.findIndex(m=>m.event===mapping.event&&(m.service??'')===mapping.service&&(m.carrier??'')===mapping.carrier&&m.source===mapping.source);eventDraft=mappingIndex>=0?{...source.mappings[mappingIndex]}:mapping;makeGoal=false;unmapEvent=false;mappingPreview=null;mappingOpen=true;tool='';error=''}
 function mappingDefinition(){const base=active??draft;const index=mappingIndex;if(unmapEvent)return removeEventMapping(base,index);return editEventDefinition(base,eventDraft,index,makeGoal)}
  async function previewMapping(){mappingPreview=await mutate('preview',mappingDefinition(),'')}
  async function saveMapping(){const result=await mutate('definitions',mappingDefinition(),'Definition activated');if(result){mappingOpen=false;draftLoaded=false;await refresh()}}
  function exploreReference(next:string,start='',end=''){selectedReference=null;exploration={mode:next,start,end};applyFilters()}
  function exploreNode(next:string){exploreReference(next,next==='origin-forward'?eventForStage(selectedStep):'',next==='goal-backward'?eventForStage(selectedStep):'')}
  function referenceDialog(next='overview'){viewMode=next;viewName='';viewStart=next==='origin-forward'?eventForStage(selectedStep):'';viewEnd=next==='goal-backward'?eventForStage(selectedStep):'';if(next==='overview'&&exploration){viewMode=exploration.mode;viewStart=exploration.start;viewEnd=exploration.end}if(next==='overview'&&selectedReference){viewMode=selectedReference.mode;viewStart=selectedReference.start;viewEnd=selectedReference.end}tool='references';menuOpen=false}
  function openTool(next:string){if(readOnly&&['configuration','invitations'].includes(next))return;tool=next;menuOpen=false;if(next==='configuration'){if(active)draft={...active,mappings:active.mappings.map(m=>({...m}))};preview=null}}

  let requestGeneration=0, stream:EventSource|null=null, poll:ReturnType<typeof setInterval>|undefined;
  const emptyModel:Model={journeys:[],nodes:[],edges:[],stats:{},diagnostics:[],unassigned:[],policy:'',warnings:[]};
  let model=$derived(snapshot?.model??emptyModel);
  let active=$derived.by(()=>{const a=snapshot?.activeDefinition;return typeof a==='object'?a:snapshot?.definitions?.find(d=>d.version===a)??snapshot?.definitions?.at(-1)});
  let events=$derived(discoveryChoices(snapshot?.discovered,snapshot?.evidence??[]));
  let versions=$derived(snapshot?.appVersions??[...new Set((snapshot?.evidence??[]).map(e=>e.version||'unknown'))].sort());
  let scopes=$derived(snapshot?.appScopes??[...new Set((snapshot?.evidence??[]).map(e=>e.scope).filter(Boolean))].sort());
  let currentNode=$derived(model.nodes?.find(n=>n.id===selectedStep)??snapshot?.baselineModel?.nodes?.find(n=>n.id===selectedStep));
  let discoveryNodes=$derived(showDiscovery?events.filter(([name])=>!active?.mappings.some(m=>m.event===name)).map(([name,info])=>({id:'event:'+name,label:name,occurrences:info.count})):[]);
  let errorConnections=$derived(errorEvidence(model).edges);
  let nodeEvidenceModel=$derived(model.nodes.some(n=>n.id===selectedStep)?model:(mode==='live'&&baseline?snapshot?.baselineModel:model)??model);
  let selectedEvent=$derived(!currentNode&&selectedStep.startsWith('event:')?selectedStep.slice(6):'');
  let nodeMappings=$derived((active?.mappings??[]).filter(m=>m.step===selectedStep));
  let currentEdge=$derived(model.edges?.find(e=>e.from===edgeFrom&&e.to===edgeTo)??snapshot?.baselineModel?.edges?.find(e=>e.from===edgeFrom&&e.to===edgeTo));
  let highlighted=$derived(lensEvidence(model,lens));
  let journeys=$derived((model.journeys??[]).filter(j=>(!selectedStep||(selectedEvent?(j.evidence??[]).some(e=>e.name===selectedEvent):(j.path??[]).includes(selectedStep)))&&(!selectedEdge||transitions(j).some(([a,b])=>edgeKey(a,b)===selectedEdge))&&(lens==='none'||highlighted.journeyIds.has(j.id))));
  let stats=$derived(model.stats??{});
  let summaryGroups=$derived(mergeSummaryGroups(snapshot?.summary??[]));
  const histogramSamples=(h:Record<string,number>)=>Object.values(h).reduce((n,count)=>n+count,0);
  let pathGroups=$derived.by(()=>{const groups=new Map<string,{path:string[],definition:number,version:string,count:number,eligible:number,denominator:number}>();for(const j of model.journeys??[]){const displayPath=(j.steps?.length?j.steps.map(step=>(step.gapBefore?'⋯ [window gap] ⋯ ':'')+step.step):j.path)??[];const key=JSON.stringify([j.definition,j.version,displayPath]);const g=groups.get(key)??{path:displayPath,definition:j.definition,version:j.version,count:0,eligible:0,denominator:(model.journeys??[]).filter(v=>v.definition===j.definition&&v.version===j.version&&!v.partial&&!v.rightCensored&&v.status!=='active').length};g.count++;if(!j.partial&&!j.rightCensored&&j.status!=='active')g.eligible++;groups.set(key,g)}return [...groups.values()].sort((a,b)=>a.count-b.count)});
  function pathText(j:Journey,limit=Infinity){if(j.steps?.length)return j.steps.slice(0,limit).map((s,i)=>(i?(s.gapBefore?' ⋯ [window gap] ⋯ ':' → '):'')+s.step).join('');return (j.path??[]).slice(0,limit).join(' → ')}
  function query(){const q=new URLSearchParams({mode});if(from&&mode==='historical')q.set('from',isoLocal(from));if(to&&mode==='historical')q.set('to',isoLocal(to));if(version)q.set('version',version);if(definition)q.set('definition',definition);if(scope)q.set('scope',scope);if(liveStart)q.set('liveStart',liveStart);if(baseline&&mode==='live')q.set('baseline','1');if(exploration){q.set('referenceMode',exploration.mode);q.set('referenceStart',exploration.start);q.set('referenceEnd',exploration.end);q.set('startOccurrence',endpointStart);q.set('endOccurrence',endpointEnd)}if(selectedReference){q.set('scope',scope);q.set('version',version);q.set('definition',definition);q.set('from',referenceBound(from,selectedReference.from));q.set('to',referenceBound(to,selectedReference.to));q.set('reference',String(selectedReference.id));q.set('startOccurrence',endpointStart);q.set('endOccurrence',endpointEnd)}return q.toString()}
  function clearAccess(){const wasViewer=readOnly;authenticated=false;snapshot=null;draftLoaded=false;csrf='';requestGeneration++;timelineGeneration++;timelineData=null;stream?.close();stream=null;tool='';mappingOpen=false;menuOpen=false;selectedReference=null;selectedStep='';selectedEdge='';exploration=null;notice='';mappingPreview=null;preview=null;pendingReferenceDelete=null;pendingDelete=null;draft={version:0,goal:'',mappings:[],fallbackTiming:false};eventDraft={event:'',step:'',source:'',kind:'step',key:'',value:''};if(wasViewer)invitationEnded=true;}
  function acceptSession(result:{csrf:string;role?:string;expires?:string}){csrf=result.csrf;role=result.role==='viewer'?'viewer':'owner';accessExpires=result.expires??'';authenticated=true;invitationEnded=false;}
  async function api(path:string,body?:unknown){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===401&&path!=='login'&&path!=='invitations/redeem'){clearAccess();throw new Error(t(readOnly?'Viewer access ended. Ask the owner for a new invitation.':'Session expired. Sign in again.'))};let data:any={};try{const raw=await r.text();try{data=JSON.parse(raw)}catch{data={error:raw.slice(0,240)}}}catch{};if(!r.ok)throw new Error(typeof data.error==='string'?t(data.error.trim()):t('Request failed. Try again.'));return data}
  async function checkSession(){if(sessionCheck||!authenticated)return;sessionCheck=true;try{const result=await api('session');if(authenticated){role=result.role==='viewer'?'viewer':'owner';accessExpires=result.expires??''}}catch(e){if(authenticated)error=e instanceof Error?e.message:t('Request failed. Try again.')}finally{sessionCheck=false}}
  async function redeemInvitation(){if(!invitationToken||authenticated&&role==='owner')return;busy=true;error='';try{const result=await api('invitations/redeem',{token:invitationToken});invitationToken='';clearAccess();acceptSession(result);await refresh();connect()}catch{error=t('This invitation is unavailable, expired, already used or revoked. Ask the owner for a new link.')}finally{busy=false}}
  async function login(e:SubmitEvent){e.preventDefault();busy=true;error='';try{const result=await api('login',{passphrase});acceptSession(result);passphrase='';await refresh();connect()}catch(e){error=e instanceof Error?e.message:t('Request failed. Try again.')}finally{busy=false}}
  async function logout(){try{await api('logout',{})}finally{clearAccess()}}
  async function refresh(){if(!authenticated)return;const generation=++requestGeneration;loading=true;try{const data:Snapshot=await api('snapshot?'+query());if(!acceptsSnapshot(generation,requestGeneration))return;snapshot=data;error='';if(!draftLoaded){const d=typeof data.activeDefinition==='object'?data.activeDefinition:data.definitions.at(-1);if(d){draft=structuredClone(d);draftLoaded=true}}}catch(e){if(acceptsSnapshot(generation,requestGeneration))error=e instanceof Error?e.message:t('Request failed. Try again.')}finally{if(acceptsSnapshot(generation,requestGeneration))loading=false}}
  function connect(){stream?.close();if(!authenticated||mode!=='live'){connection='Historical snapshot';return};connection='Connecting';const sub=new EventSource('/api/events?'+query());stream=sub;sub.onopen=()=>{if(stream===sub)connection='Connected'};const update=()=>{if(stream!==sub||!authenticated)return;if(!paused)void refresh();else connection='Update available'};sub.onmessage=update;sub.addEventListener('update',update);sub.addEventListener('reset',update);sub.addEventListener('invalidate',update);sub.onerror=()=>{if(stream===sub){connection='Reconnecting';if(readOnly)void checkSession()}};}
  function applyFilters(e?:SubmitEvent){e?.preventDefault();if(from&&to&&new Date(from)>=new Date(to)){error=t('Date range must end after its beginning.');return};requestGeneration++;void refresh();connect()}
  function setMode(next:string){if(mode===next)return;mode=next;if(next==='live'){liveStart=new Date().toISOString();paused=false}selectedReference=null;exploration=null;applyFilters()}
  function togglePause(){paused=!paused;if(!paused){void refresh();connect()}}
  function selectScope(next:string){scope=next;selectedStep='';selectedEdge='';tool='';applyFilters()}
  async function mutate(path:string,body:unknown,message:string){if(readOnly){error=t('Read-only access');return;}busy=true;notice='';error='';try{const response=await api(path,body);if(message)notice=t(message);await refresh();return response}catch(e){error=e instanceof Error?e.message:t('Request failed. Try again.')}finally{busy=false}}
  function addMapping(){draft.mappings=[...draft.mappings,{event:events[0]?.[0]??'',step:'',source:'',kind:'step',key:'',value:''}]}
  async function activate(){const result=await mutate('definitions',draft,'Definition activated');if(result){draftLoaded=false;await refresh();preview=null}}
  async function previewDefinition(){preview=await mutate('preview',draft,'')}
  async function saveView(){if(readOnly)return;if(!viewName.trim()){error=t('Name')+' required';return};const bounds=captureReferenceBounds(mode,from?isoLocal(from):'',to?isoLocal(to):'',liveStart,new Date().toISOString());const v={name:viewName.trim(),mode:viewMode,start:viewStart,end:viewEnd,startOccurrence:endpointStart,endOccurrence:endpointEnd,version,definition:Number(definition||0),scope,layout,lens,...bounds};const saved=await mutate('views',v,'Reference saved');if(saved){openView(saved);tool=''}}
  async function deleteReference(view:SavedView){
    if(readOnly||pendingReferenceDelete!==view.id)return;
    busy=true;error='';notice='';
    try{
      await api('views/delete',{id:view.id});
      if(selectedReference?.id===view.id){selectedReference=null;exploration=null;requestGeneration++;}
      pendingReferenceDelete=null;notice=t('Reference deleted');await refresh();connect();
    }catch(e){error=e instanceof Error?e.message:t('Request failed. Try again.')}finally{busy=false}
  }
  function openView(v:SavedView){exploration=null;selectedReference=v;endpointStart=v.startOccurrence??'first';endpointEnd=v.endOccurrence??'last';mode='historical';version=v.version;definition=String(v.definition||'');scope=v.scope??'';if(v.layout&&['hierarchy','force','sankey'].includes(v.layout))layout=v.layout as Layout;if(v.lens)lens=v.lens;from=v.from?v.from.replace(/Z$/,''):'';to=v.to?v.to.replace(/Z$/,''):'';selectedStep='';selectedEdge='';tool='';applyFilters()}
  function referenceEvidence(j:Journey){return j.evidence??[];}
  function boundaryMissing(j:Journey){if(!selectedReference)return false;const v=selectedReference;const ns=(j.evidence??[]).map(e=>e.name);return v.mode==='segment'&&(!ns.includes(v.start)||!ns.includes(v.end))}
  function summaryText(v:any){return JSON.stringify(v??{},null,2)}
  async function copyEvidence(e:Evidence){try{await navigator.clipboard.writeText(evidenceCopy(e));copied=String(e.id);setTimeout(()=>copied='',2000)}catch{error='Copy unavailable. Select the displayed sanitized text.'}}
  function deletionConfirmation(){return pendingDelete==='visit'?deleteScope:pendingDelete==='bucket'?summaryBucket:'DELETE'}
  async function deleteData(){if(readOnly)return;if(deleteConfirm!==deletionConfirmation())return;if(pendingDelete==='visit'){await mutate('delete',{scope:deleteScope},'Visit deleted')}else if(pendingDelete==='bucket'){if(!/^\d{4}-\d{2}-\d{2}$/.test(summaryBucket))return;await mutate('delete',{app:true,bucket:summaryBucket},'Summary day deleted')}else{await mutate('delete',{app:true},'Application disabled')};pendingDelete=null;deleteConfirm=''}
  const pct=(n:number,d:number)=>d?`${(100*n/d).toFixed(1)}%`:'—';
  onMount(()=>{let alive=true;const stored=localStorage.getItem('sentrame-language');if(stored==='fr')language='fr';const invitation=invitationLocation(window.location);if(invitation){invitationToken=invitation.token;history.replaceState(null,'',invitation.cleanURL);}api('session').then(async d=>{if(!alive)return;acceptSession(d);if(!invitationToken){await refresh();connect()}}).catch(()=>{error=''}).finally(()=>{if(alive)sessionReady=true});poll=setInterval(()=>{if(authenticated&&readOnly){if(accessExpires&&Date.parse(accessExpires)<=Date.now()){clearAccess();return;}void checkSession()}if(authenticated&&!invitationToken&&!paused&&mode==='live')void refresh()},5000);return()=>{alive=false;requestGeneration++;stream?.close();invitationToken='';if(poll)clearInterval(poll)}});
  function setLanguage(l:Language){language=l;document.documentElement.lang=l;localStorage.setItem('sentrame-language',l)}
</script>

<svelte:window onpointerdowncapture={()=>{document.documentElement.dataset.pointerFocus='true'}} onkeydowncapture={e=>{if(e.key==='Tab')delete document.documentElement.dataset.pointerFocus}} onkeydown={e=>{if(e.key==='Escape')menuOpen=false}}/>
<svelte:head><title>Sentrame · {t('Journey explorer')}</title></svelte:head>
<a class="skip" href="#main">Skip to content / Aller au contenu</a>
<header class="masthead" class:compact={authenticated&&!invitationToken}>
  <div class="brand"><svg width="34" height="34" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M6 9h10a7 7 0 0 1 0 14H6m20-14H16a7 7 0 0 0 0 14h10" stroke="currentColor" stroke-width="2.5"/><circle cx="6" cy="9" r="3" fill="currentColor"/><circle cx="26" cy="23" r="3" fill="currentColor"/></svg><span>sentrame</span></div>
  <span class="tagline">{t('The thread between events')}</span>
  <div class="mast-actions"><span class="workspace-badge"><span aria-hidden="true">◌</span> {t('Synthetic workspace')}</span><div class="languages" aria-label="Language / Langue"><button class:active={language==='en'} onclick={()=>setLanguage('en')} lang="en" aria-pressed={language==='en'}>EN</button><button class:active={language==='fr'} onclick={()=>setLanguage('fr')} lang="fr" aria-pressed={language==='fr'}>FR</button></div>{#if authenticated}<button class="header-button" onclick={logout}>{t('Sign out')}</button>{/if}</div>
</header>
<main id="main" class:workspace-main={authenticated&&!invitationToken}>
  {#if invitationToken}
    <section class="login-layout"><div><p class="eyebrow">SENTRAME · {t('Temporary viewer')}</p><h1>{t('Explore together.')}<br/><em>{t('Read-only access.')}</em></h1><p class="lede">{t('This invitation grants temporary access to the whole application: historical and live journeys, references, errors and sanitized diagnostics. It does not allow changes.')}</p></div><div class="login-card"><h2>{t('Temporary invitation')}</h2>{#if authenticated&&role==='owner'}<p>{t('You are signed in as the owner. Sign out before accepting a viewer invitation, or open the link in a separate browser profile.')}</p><button onclick={logout} disabled={busy}>{t('Sign out')}</button>{:else}<p class="muted">{t('The link can be redeemed once. The owner can revoke access at any time.')}</p><button onclick={redeemInvitation} disabled={busy||!sessionReady}>{t(!sessionReady?'Checking access…':busy?'Opening…':'Open read-only workspace')}</button>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</div></section>
  {:else if !authenticated&&invitationEnded}
    <section class="login-layout"><div><p class="eyebrow">SENTRAME · {t('Temporary viewer')}</p><h1>{t('Viewer access ended.')}</h1><p class="lede">{t('Your invitation expired, was revoked, or its session ended. Ask the owner for a new invitation link.')}</p></div><div class="login-card"><h2>{t('Access is closed')}</h2><p>{t('The workspace has been cleared from this page. Previously copied information cannot be recalled.')}</p><button class="secondary" onclick={()=>{invitationEnded=false;role='owner';error=''}}>{t('Owner sign in')}</button></div></section>
  {:else if !authenticated}
    <section class="login-layout">
      <div><p class="eyebrow">SENTRAME · {t('Owner access')}</p><h1>{t('Follow what happened.')}<br/><em>{t('Understand the path.')}</em></h1><p class="lede">{t('Observed journeys, healthy loops, and the evidence in between.')}</p><p class="privacy-line">{t('No personal identity joins')} · {t('Local qualification only')}</p></div>
      <form class="login-card" onsubmit={login}><span class="small-icon" aria-hidden="true">↔</span><h2>{t('Open workspace')}</h2><p class="muted">{t('Owner access')} · {t('Sentrame demonstration')}</p><label for="passphrase">{t('Passphrase')}</label><input id="passphrase" type="password" bind:value={passphrase} autocomplete="current-password" required/><button type="submit" disabled={busy||!passphrase}>{busy?t('Signing in…'):t('Open workspace')} <span aria-hidden="true">→</span></button>{#if error}<p class="error" role="alert">{error}</p>{/if}</form>
    </section>
  {:else}
    <nav class="button-row" aria-label={t('Exploration mode')}><button aria-pressed={explorationMode==='trace'} onclick={()=>explorationMode='trace'}>{t('Traces')}</button><button aria-pressed={explorationMode==='journey'} onclick={()=>explorationMode='journey'}>{t('Journeys')}</button></nav>
    {#if explorationMode==='trace'}<Traces request={api} revision={snapshot?.revision??0} {language} {readOnly} onconfigure={openEvidenceMapping}/>{:else}
    <section class="workspace" aria-label={t('Journey workspace')}>
      <div class="workspace-toolbar">
        <div class="workspace-title"><span class="eyebrow">{t('Sentrame demonstration')}</span><strong>{selectedReference?.name??t('Journey workspace')}</strong></div>
        <div class="segmented layouts" aria-label={t('Graph view')}>{#each [['hierarchy','Hierarchy'],['force','Force'],['sankey','Sankey']] as [id,label]}<button class:chosen={layout===id} aria-pressed={layout===id} onclick={()=>layout=id as Layout}>{t(label)}</button>{/each}</div>
        <div class="workspace-tools">
          <button class="quiet-button" onclick={()=>openTool('filters')}>{t(mode==='live'?'Live':'Historical')} <span aria-hidden="true">⌄</span></button>
          <label class="lens-control"><span>{t('Highlight')}</span><select aria-label={t('Graph highlight')} bind:value={lens}><option value="none">{t('None')}</option><option value="rare">{t('Rare paths')}</option><option value="endings">{t('Endings')}</option><option value="exceptions">{t('Warnings & exceptions')}</option><option value="recovery">{t('Recovery')}</option></select></label>
          <button class="quiet-button" onclick={()=>referenceDialog()}>{t('References')}</button>
          <div class="workspace-menu"><button class="icon-button" aria-label={t('Workspace menu')} aria-expanded={menuOpen} onclick={()=>menuOpen=!menuOpen}>☰</button>{#if menuOpen}<div class="menu-popover"><button onclick={()=>{showDiscovery=!showDiscovery;menuOpen=false}}>{t(showDiscovery?'Hide discovered events':'Show discovered events')}</button><button onclick={()=>openTool('discovery')}>{t('Unmapped events')}</button>{#if !readOnly}<button onclick={()=>openTool('configuration')}>{t('Mappings & goal')}</button><button onclick={()=>referenceDialog('overview')}>{t('Save current view…')}</button><button onclick={()=>openTool('invitations')}>{t('Temporary viewers')}</button>{/if}<button onclick={()=>openTool('errors')}>{t('Errors & exceptions')}</button><button onclick={()=>openTool('lifecycle')}>{t('Data lifecycle')}</button><button onclick={()=>openTool('about')}>{t('About this evidence')}</button></div>{/if}</div>
        </div>
      </div>
      <div class="workspace-context">
        {#if scope}<button class="context-chip selected-scope" aria-label={t('Clear selected visit')+': '+scope} onclick={()=>{scope='';selectedStep='';selectedEdge='';applyFilters()}}><span>{t('Visit / operation')} · {scope.slice(0,8)}</span><span aria-hidden="true">×</span></button>{:else}<span class="context-chip">{t('All app traffic')}</span>{/if}{#if version}<button class="context-chip" onclick={()=>{version='';applyFilters()}}>{version} ×</button>{/if}{#if definition}<button class="context-chip" onclick={()=>{definition='';applyFilters()}}>v{definition} ×</button>{/if}
        {#if exploration}<button class="context-chip" onclick={()=>{exploration=null;applyFilters()}}>{t(exploration.mode==='goal-backward'?'Paths into here':exploration.mode==='origin-forward'?'Paths from here':'Between stages')} · {exploration.start||exploration.end} ×</button>{/if}
        {#if selectedReference}<button class="context-chip" onclick={()=>{selectedReference=null;applyFilters()}}>{t('Clear reference')} ×</button>{/if}
        {#if segmentStart}<span class="context-chip">{t('Select an end stage')} · {segmentStart}<button class="text-button" onclick={()=>segmentStart=''}>{t('Cancel')}</button></span>{/if}
        {#if mode==='live'}<label class="toggle"><input type="checkbox" bind:checked={baseline} onchange={()=>applyFilters()}/>{t('Seven-day baseline')}</label><button class="text-button" onclick={togglePause}>{t(paused?'Resume updates':'Pause updates')}</button>{/if}
        {#if readOnly}<span class="context-chip" role="status">{t('Read-only access')} · {t('Expires')}: {dateTime(accessExpires)}</span>{/if}
        <span class="workspace-freshness"><span class="status-dot" class:paused></span>{t(paused?'Paused · collection continues':connection)}{loading?' · …':''}</span>
      </div>
      {#if error}<div class="workspace-alert error-banner" role="alert">{error}<button class="text-button" onclick={()=>void refresh()}>{t('Refresh')}</button></div>{/if}
      {#if notice}<div class="workspace-alert notice" role="status">{notice}<button class="text-button" onclick={()=>notice=''}>×</button></div>{/if}
      <div class="workspace-canvas" class:inspecting={!!selectedStep||!!selectedEdge}>
        <Graph {model} baseline={mode==='live'&&baseline?snapshot?.baselineModel:null} {language} selected={selectedStep} onselect={chooseNode} {selectedEdge} onedge={chooseEdge} {layout} {lens} discovery={discoveryNodes} goal={active?.mappings.find(m=>m.event===active?.goal)?.step??''}/>
        {#if selectedStep||selectedEdge}
          <aside class="node-inspector" aria-label={t('Selection details')}>
            <header class="inspector-heading"><p class="eyebrow">{t(selectedEdge?'Observed transition':selectedEvent?'Discovered event':'Journey stage')}</p><button class="icon-button" aria-label={t('Close inspector')} onclick={()=>{selectedStep='';selectedEdge=''}}>×</button></header>
            <h2>{selectedEdge?edgeFrom+' → '+edgeTo:currentNode?.label??selectedEvent??selectedStep}</h2>
            {#if selectedEdge&&currentEdge}
              <p class="muted">{t(model.edges.some(e=>e.from===edgeFrom&&e.to===edgeTo)?'Current selection':'Baseline only')}</p>
              <dl class="inspector-counts"><div><dt>{t('Occurrences')}</dt><dd>{currentEdge.occurrences}</dd></div><div><dt>{t('Journeys')}</dt><dd>{currentEdge.journeys}</dd></div><div><dt>{t('Visits')}</dt><dd>{currentEdge.visits}</dd></div></dl>
              <p class="inspector-note">{t('A transition is observed adjacency, not proof of cause. Open journeys to inspect its order and context.')}</p>
              {#if errorConnections.has(selectedEdge)}<p class="error-evidence-note">! {t('Error evidence on this connection')}</p>{/if}<button class="secondary" onclick={()=>openTool('evidence')}>{t('Show journeys')} ({journeys.length})</button>
              <div class="button-row"><button class="text-button" onclick={()=>chooseNode(edgeFrom)}>{t('Inspect beginning')}</button><button class="text-button" onclick={()=>chooseNode(edgeTo)}>{t('Inspect end')}</button></div>
            {:else if selectedEvent}
              <span class="subtle-badge">{t('Unmapped event')}</span><p class="inspector-note">{t('Received telemetry without an assigned journey meaning. No relationship is inferred from proximity.')}</p>
              <p class="muted">{events.find(([name])=>name===selectedEvent)?.[1].count??0} {t('Records in app retention')}</p>
              {#if !readOnly}<button onclick={()=>openMapping(selectedEvent)}>{t('Configure event…')}</button>{/if}
            {:else if currentNode}
              {#if mode==='live'&&baseline}<p class="muted">{t(nodeEvidenceModel===model?'Current selection':'Baseline only')}</p>{/if}
              <dl class="inspector-counts"><div><dt>{t('Occurrences')}</dt><dd>{currentNode.occurrences}</dd></div><div><dt>{t('Journeys')}</dt><dd>{currentNode.journeys}</dd></div><div><dt>{t('Visits')}</dt><dd>{currentNode.visits}</dd></div></dl>
              {#if currentNode.stops||currentNode.pending}<p class="inspector-note">{currentNode.stops} {t('Potential stops')} · {currentNode.pending} {t('Pending')}<br/>{t('Silence does not establish failure.')}</p>{/if}
              {#each [['Incoming','to','from'],['Outgoing','from','to']] as [label,match,other]}
                <section class="inspector-section"><h3>{t(label)}</h3>{#each nodeEvidenceModel.edges.filter(e=>(e as any)[match]===selectedStep) as edge}<button class="neighbor-row" onclick={()=>chooseEdge(edge.from,edge.to)}><span>{(edge as any)[other]===selectedStep?t('Repeated here'):(edge as any)[other]}</span><small>{edge.occurrences} {t('transitions')}</small></button>{:else}<p class="muted">{t('No observed transitions in this selection')}</p>{/each}</section>
              {/each}
              <section class="inspector-section"><h3>{t('Time at stage')}</h3>{#each currentNode.timing??[] as timing}<div class="timing-detail"><span class="subtle-badge">{t(timing.basis==='native-inclusive'?'Native inclusive operation':timing.basis==='measured-elapsed'?'Measured elapsed':timing.basis==='observed-active'?'Observed active':'Next-event estimated')} · v{timing.definition} · {timing.computation??''}</span><dl><div><dt>{t('Median')}</dt><dd>{duration(timing.medianMs,t('Unavailable'))}</dd></div><div><dt>{t('Slower cases (p90)')}</dt><dd>{duration(timing.p90Ms,t('Unavailable'))}</dd></div></dl><small>{timing.samples} {t('samples')} · {timing.excluded} {t('excluded')} · {pct(timing.completeness,1)} {t('complete')}</small></div>{:else}<p class="muted">{t('No completed timing samples')}</p>{/each}<p class="inspector-note">{t('p90 requires 20 completed samples of the same basis. Missing ends are not zero. Elapsed time is not attention.')}</p></section>
              <section class="inspector-section"><h3>{t('Events in this stage')}</h3>{#each nodeMappings as mapping}{#if readOnly}<p class="mono">{mapping.event}</p>{:else}<button class="neighbor-row" onclick={()=>openMapping(mapping.event)}><span>{mapping.event}</span><small>{t('Configure event…')}</small></button>{/if}{/each}</section>
              <div class="inspector-actions"><button class="secondary" onclick={()=>openTool('evidence')}>{t('Show journeys')} ({journeys.length})</button><button class="quiet-button" onclick={()=>exploreNode('goal-backward')}>{t('Paths into here…')}</button><button class="quiet-button" onclick={()=>exploreNode('origin-forward')}>{t('Paths from here…')}</button><button class="quiet-button" onclick={()=>{segmentStart=eventForStage(selectedStep);selectedStep=''}}>{t('Use as beginning…')}</button></div>
            {:else}<p class="inspector-note">{t('This selection has no retained evidence in the current filters.')}</p>{/if}
          </aside>
        {/if}
      </div>
      <div class="canvas-status"><span>{stats.journeys??0} {t('Journeys')} · {stats.completed??0} {t('Completed goals')} · {stats.inactive??0} {t('Inactive')}<span class="status-extra"> · {stats.unassigned??0} {t('Unassigned records')}</span>{#if mode==='live'&&baseline} · {snapshot?.baselineModel?.stats?.journeys??0} {t('Baseline journeys')}{/if}</span><div><button class="text-button" onclick={()=>openTool('errors')}>{t('Errors')}</button><button class="text-button" onclick={()=>openTool('table')}>{t('Table')}</button><button class="text-button" onclick={()=>openTool('evidence')}>{t('Journeys & evidence')}</button></div></div>
      {#if lens==='rare'}<p class="canvas-explanation">{t('Rare: at most 10% of comparable complete paths, with at least 20 closed journeys per definition and version. Low support is not a defect.')} <button class="text-button" onclick={()=>openTool('paths')}>{t('Path counts')}</button></p>{:else if lens!=='none'}<p class="canvas-explanation">{t(lens==='endings'?'Endings distinguish completed, inactive, explicit exit and pending evidence.':lens==='recovery'?'Recovered journeys retain their earlier warnings and later continuation.':'Warnings and exceptions highlight linked journeys; proximity is not cause.')} <button class="text-button" onclick={()=>openTool('evidence')}>{t('Inspect evidence')}</button></p>{/if}
      {#if snapshot?.limits?.truncated}<p class="canvas-explanation warning">{t('Query work limit reached. Counts are partial; narrow your filters.')}</p>{/if}
    </section>
    {/if}
    {#if mappingOpen&&!readOnly}
      <Modal title={t(makeGoal?'Set operational goal':'Configure event')} onclose={()=>mappingOpen=false}>
        <form onsubmit={e=>{e.preventDefault();void saveMapping()}} oninput={()=>mappingPreview=null}>
          <p class="mono">{eventDraft.event}</p><p class="inspector-note">{t('Give this received event a journey meaning. Relationships come from ordered evidence, not this configuration.')}</p>
          <label><input type="checkbox" bind:checked={makeGoal}/>{t('Use this exact mapping as the operational goal')}</label>
 <p class="inspector-note">{t('A browser intent or generic HTTP success cannot prove persistence. Choose a trusted named commitment or a documented successful operation for that goal.')}</p>
 <fieldset class="event-fields" disabled={unmapEvent}><div class="form-grid">
 <label>{t('Service (exact; empty means any)')}<input bind:value={eventDraft.service}/></label>
 <label>{t('Carrier')}<select bind:value={eventDraft.carrier}><option value="">{t('Any carrier')}</option><option value="span">span</option><option value="span-event">span-event</option><option value="log">log</option></select></label>
 <label>{t('Timing basis')}<select bind:value={eventDraft.timing}><option value="">{t('Native span; otherwise unavailable')}</option><option value="native-span">{t('Native inclusive operation')}</option><option value="paired">{t('Explicit paired boundaries')}</option><option value="estimated">{t('Next-event estimated')}</option><option value="none">{t('Unavailable')}</option></select></label>
            <div><FieldHelp fieldId="mapping-stage" label={t('Stage')} helpLabel={t('Help: Stage')} help={[t('The name shown on the journey graph. Use a short, meaningful label such as Checkout or Vote saved. Several events can share a stage name.'),t('For stage start and stage end, use the same stage name. For activity, this name does not add a graph node.')]}/><input id="mapping-stage" aria-describedby="mapping-stage-help" bind:value={eventDraft.step} required maxlength="200"/></div>
            <div><FieldHelp fieldId="mapping-kind" label={t('Kind')} helpLabel={t('Help: Kind')} help={[t('Step: adds an occurrence to the journey path. Use this for a meaningful action or milestone, such as Vote saved.'),t('Explicit exit: ends the journey with an emitted reason, such as recipes exhausted. It does not automatically mean failure.'),t('Stage start / stage end: mark entry and exit for elapsed timing. Pair the same stage name and emitted occurrence ID from the same producer and service. The start adds a graph step; the end does not.'),t('Activity: keeps supporting evidence without adding a graph step. With activity.state set to active, visible, idle or hidden, it can support observed active-time calculations; it does not measure attention.'),t('All mapped kinds refresh the inactivity timeout. The operational goal is selected separately.')]}/><select id="mapping-kind" aria-describedby="mapping-kind-help" bind:value={eventDraft.kind}><option value="step">{t('step')}</option><option value="exit">{t('explicit exit')}</option><option value="stage-start">{t('stage start')}</option><option value="stage-end">{t('stage end')}</option><option value="activity">{t('activity')}</option></select></div>
            <div><FieldHelp fieldId="mapping-source" label={t('Trusted producer')} helpLabel={t('Help: Trusted producer')} help={[t('Choose which configured producer may match this event: Browser, Server, or Any source. Use Server for an event that proves a saved change.'),t('This uses the receiver’s trusted producer assignment. Selecting Server does not turn a browser claim into trusted server evidence.')]}/><select id="mapping-source" aria-describedby="mapping-source-help" bind:value={eventDraft.source}><option value="">{t('Any source')}</option><option value="browser">{t('Browser')}</option><option value="server">{t('Server')}</option></select></div>
            <div><FieldHelp fieldId="mapping-key" label={t('Condition key')} helpLabel={t('Help: Condition key')} help={[t("This field names a piece of information inside the event. Equals is the value that information must contain. These two fields work together to filter this event’s mapping."),t("Example: for journey.exited with {\"reason\":\"exhausted\"}, enter reason in Condition key and exhausted in Equals. Only journey.exited events with that reason match; other reasons do not."),t("Another example: for completion.entered with {\"reason\":\"agreed\"}, enter reason in Condition key and agreed in Equals."),t("Open Received examples below and look inside the event attributes. Copy the attribute name into Condition key and its value into Equals, without quotes or JSON braces. Only retained, allowed attributes can be used."),t("If you want every occurrence of this event from the selected producer, leave BOTH fields empty. You do not need a condition for a normal mapping.")]}/><input id="mapping-key" aria-describedby="mapping-key-help" bind:value={eventDraft.key}/></div>
            <div><FieldHelp fieldId="mapping-value" label={t('Equals')} helpLabel={t('Help: Equals')} help={[t("Enter the exact value you want to allow for Condition key. It is text, not a formula or search."),t("Example: Condition key = reason; Equals = exhausted. An event containing {\"reason\":\"exhausted\"} matches. {\"reason\":\"agreed\"} does not. An event without reason does not match this example either."),t("Example: Condition key = activity.state; Equals = hidden. Only events with activity.state set to hidden match this mapping."),t("Type exhausted, not reason=exhausted, not \"exhausted\", and not the whole JSON object. Capitalization matters: Exhausted is different from exhausted."),t("Leave both fields empty if you do not need this filter. Then use Preview matches to check your rule before activating it.")]}/><input id="mapping-value" aria-describedby="mapping-value-help" bind:value={eventDraft.value}/></div>
          </div></fieldset>{#if mappingIndex>=0&&!makeGoal}<label class="toggle"><input type="checkbox" bind:checked={unmapEvent} disabled={eventDraft.event===active?.goal||(active?.mappings.length??0)<=1} onchange={()=>mappingPreview=null}/>{t('Stop mapping this event')}</label>{#if eventDraft.event===active?.goal}<p class="inspector-note">{t('Choose another operational goal before removing this mapping.')}</p>{/if}{/if}
          <details><summary>{t('Received examples')}</summary>{#each (snapshot?.evidence??[]).filter(e=>e.name===eventDraft.event).slice(0,3) as event}<div class="received-example"><span>{event.source} · {event.signal} · {event.service} · {dateTime(event.time)}</span><pre>{summaryText(event.attrs)}</pre></div>{:else}<p class="muted">{t('No retained examples in the current selection.')}</p>{/each}</details>
          <p class="inspector-note">{t('Activation creates a new prospective definition. Captured journeys keep their original rule version. Browser claims cannot establish a server commitment.')}</p>
          {#if makeGoal}<p class="warning">{t('This explicitly changes the operational goal for future journeys.')}</p>{/if}
          {#if mappingPreview}<div class="preview"><h3>{t('Preview')}</h3>{#if mappingPreview.conflict}<p class="warning">{mappingPreview.conflict}</p>{/if}{#if unmapEvent}<p>{t('This event will no longer be mapped in the next definition.')}</p>{/if}<p>{mappingPreview.matches?.[eventDraft.event]??0} {t('Matching records')} · {mappingPreview.missingContextByEvent?.[eventDraft.event]??0} {t('without safe journey context')} · {t('Trace exploration remains available')}</p></div>{/if}
          {#if error}<p class="error" role="alert">{error}</p>{/if}
          <div class="button-row"><button type="button" class="secondary" disabled={busy} onclick={previewMapping}>{t('Preview matches')}</button><button disabled={busy||!eventDraft.step.trim()||!mappingDefinition().goal||!mappingPreview||!!mappingPreview.conflict}>{t('Activate new definition')}</button></div>
        </form>
      </Modal>
    {/if}
    {#if tool}
      <Modal title={t(({filters:'Time & filters',references:'Reference views',table:'Map and timing table',evidence:'Ordered journeys',paths:'Observed paths',discovery:'Unmapped events',configuration:'Mappings & goal',invitations:'Temporary viewers',lifecycle:'Data lifecycle',about:'About this evidence',errors:'Errors & exceptions'} as Record<string,string>)[tool]??tool)} wide={['errors','filters','table','evidence','paths','lifecycle','configuration','references','invitations'].includes(tool)} onclose={()=>tool=''}>
        {#if error}<p class="error" role="alert">{error}</p>{/if}
        {#if tool==='invitations'&&!readOnly}<Invitations {language} request={api}/>{:else if tool==='filters'}
          <div class="segmented"><button class:chosen={mode==='historical'} onclick={()=>setMode('historical')}>{t('Historical')}</button><button class:chosen={mode==='live'} onclick={()=>setMode('live')}>{t('Live')}</button></div>
          {#if mode==='historical'}
            <div class="timeline-context-toolbar"><div class="segmented" aria-label={t('Timeline context')}>{#each ['1h','24h','7d','30d'] as window}<button class:chosen={timelineWindow===window} aria-pressed={timelineWindow===window} onclick={()=>timelineWindow=window}>{t(window)}</button>{/each}</div><span class="muted">{t('Chart context')}</span>{#if timelineLoading}<span class="muted" role="status">{t('Loading…')}</span>{/if}</div>
            {#if timelineError}<p class="warning" role="alert">{timelineError}<button class="text-button" onclick={()=>void refreshTimeline(timelineWindow,scope,version,definition)}>{t('Refresh')}</button></p>{:else}<Timeline data={timelineData} {from} {to} {language} onrange={chooseTimeRange}/>{/if}
            <div class="quick-times"><span>{t('Quick range')}</span><button class="chip" onclick={()=>recentRange(.25)}>{t('Last 15 minutes')}</button><button class="chip" onclick={()=>recentRange(1)}>{t('Last hour')}</button><button class="chip" onclick={()=>recentRange(24)}>{t('Last 24 hours')}</button></div>
          {:else}<p class="inspector-note">{t('Live observation')}: {dateTime(liveStart)} → {t('Live')}{#if baseline}<br/>{t('App-wide baseline')}: {dateTime(Date.parse(liveStart)-7*86400000)} → {dateTime(liveStart)} · {t('bounds fixed')}{/if}</p>{/if}
          <form class="workspace-filters" onsubmit={applyFilters}><div class="form-grid"><label>{t('Version')}<select bind:value={version}><option value="">{t('All versions')}</option>{#each versions as v}<option value={v}>{v}</option>{/each}</select></label><label>{t('Definition')}<select bind:value={definition}><option value="">{t('All definitions')}</option>{#each snapshot?.definitions??[] as d}<option value={d.version}>v{d.version} · {d.goal}</option>{/each}</select></label></div>
            <p class="inspector-note">{t('To follow one visit, select a node, open its journeys and choose Follow this visit. No session ID is needed.')}</p>
            <details class="advanced-filters"><summary>{t('Advanced: exact times or correlation ID')}</summary><div class="form-grid"><label>{t('Correlation ID (optional)')}<input type="search" bind:value={scope} placeholder={t('Paste a known session or operation ID')}/></label>{#if mode==='historical'}<label>{t('From')} · UTC<input type="datetime-local" step="0.001" bind:value={from}/></label><label>{t('To')} · UTC<input type="datetime-local" step="0.001" bind:value={to}/></label>{/if}</div><p class="inspector-note">{t('This code groups related events; it does not identify a person or link separate visits.')}</p></details><button type="submit">{t('Apply filters')}</button></form>
        {:else if tool==='errors'}<Errors {language} request={readErrors} onfollow={exploreError}/>
        {:else if tool==='table'}        <details class="panel data-table" open><summary>{t('Map and timing table')}</summary><div class="table-wrap"><table><caption>{t('Traffic counts; timing remains separate by basis and definition.')}</caption><thead><tr><th>{t('Stage')}</th><th>{t('Occurrences')}</th><th>{t('Journeys')} / {t('Visits')}</th><th>{t('Potential stops')} / {t('Pending')}</th><th>{t('Timing basis')}</th><th>{t('Median')}</th><th>{t('Slower cases (p90)')}</th><th>{t('Samples / exclusions')}</th></tr></thead><tbody>{#each model.nodes??[] as n}{#each n.timing?.length?n.timing:[null] as timing}<tr><th scope="row"><button class="text-button" onclick={()=>chooseNode(n.id)}>{n.label}</button></th><td>{n.occurrences}</td><td>{n.journeys} / {n.visits}</td><td>{n.stops} / {n.pending}</td><td>{timing?.basis??t('Unavailable')}{#if timing} · v{timing.definition}{/if}</td><td>{duration(timing?.medianMs,t('Unavailable'))}</td><td>{duration(timing?.p90Ms,t('Unavailable'))}</td><td>{timing?.samples??0} / {timing?.excluded??0}{#if timing}<small>{pct(timing.completeness,1)} complete</small>{/if}</td></tr>{/each}{/each}</tbody></table></div><p class="muted footnote">{t("Potential stops count eligible journeys ending here; pending journeys are censored. p90 requires at least 20 completed samples of the same timing basis. Missing ends are never zero.")}</p><div class="table-wrap"><table><caption>{t('Observed transitions')}</caption><thead><tr><th>{t('Transition')}</th><th>{t('Occurrences')}</th><th>{t('Journeys')}</th><th>{t('Visits')}</th></tr></thead><tbody>{#each model.edges??[] as e}<tr><th scope="row"><button class="text-button" onclick={()=>{chooseEdge(e.from,e.to);tool=''}}>{e.from} → {e.to}{#if errorConnections.has(edgeKey(e.from,e.to))} · ! {t('Error evidence')}{/if}</button></th><td>{e.occurrences}</td><td>{e.journeys}</td><td>{e.visits}</td></tr>{/each}</tbody></table></div></details>

        {:else if tool==='paths'}        <details class="panel"><summary>{t("Observed path frequencies · rare paths remain visible")}</summary><p class="muted footnote">{t("One row per observed sequence, definition and initial app version. Rarity uses closed, non-partial, uncensored journeys; at least 20 comparable journeys and at most 10% sequence share. Partial and ongoing observations remain in total counts, not the rarity denominator.")}</p><div class="table-wrap"><table><thead><tr><th>{t("Observed path")}</th><th>{t('Definition')} / {t('Version')}</th><th>{t('Journeys')}</th><th>{t("Eligible / comparable")}</th><th>{t("Share")}</th></tr></thead><tbody>{#each pathGroups.slice(0,200) as group}<tr><th scope="row">{group.path.join(' → ')}</th><td>v{group.definition} / {group.version||'unknown'}</td><td>{group.count}</td><td>{group.eligible}/{group.denominator}</td><td>{pct(group.eligible,group.denominator)}{group.denominator<20?' · low support':''}</td></tr>{/each}</tbody></table></div>{#if pathGroups.length>200}<p class="warning">Showing 200/{pathGroups.length} path groups. Narrow filters to inspect the rest.</p>{/if}</details>

        {:else if tool==='evidence'}        <section class="journeys" aria-labelledby="paths-title"><div class="section-title"><div><p class="eyebrow">{t("Evidence before inference")}</p><h2 id="paths-title">{t('Ordered journeys')}</h2></div><span class="muted">{journeys.length} {t('of')} {model.journeys?.length??0}</span></div>{#if selectedStep}<p class="selection-note">{t('Inspect paths containing')}: <strong>{selectedStep}</strong>. Intermediate evidence is preserved. <button class="text-button" onclick={()=>selectedStep=''}>{t('Show all paths')}</button></p>{/if}
        {#if journeys.length===0}<div class="empty-state"><span aria-hidden="true">↔</span><h3>{t('No journeys in this view')}</h3><p>{t('Receive synthetic telemetry, then check the filters and mappings.')}</p></div>{/if}
        {#each journeys as j (j.id)}
          <details class="journey-card"><summary><span class="chevron" aria-hidden="true">›</span><span class="journey-heading"><strong>{pathText(j,5)||j.id}{#if (j.path?.length??0)>5} → …{/if}</strong></span><span class="journey-meta">{dateTime(j.start)}<small>v{j.definition} · {j.version||'unknown'}{#if j.mixedVersion} · {t('Mixed versions')}{/if}</small></span><span class={`outcome ${j.status}`}>{j.status==='completed'?'✓':j.status==='active'?'◉':j.status==='inactive'?'◷':'↗'} {t(j.status==='completed'?'Completed':j.status==='active'?'Active':j.status==='inactive'?'Inactive':'Exited')}</span></summary>
          <div class="journey-body"><div class="journey-actions"><button class="secondary" onclick={()=>selectScope(j.scope)}>{t(j.evidence?.every(e=>e.source==='server')?'Follow this operation':'Follow this visit')}</button>{#if j.recovered}<span class="outcome completed">↪ {t('Recovered')}</span>{/if}{#if j.partial}<span class="outcome inactive">{t('Partial beginning')}</span>{/if}<span class="muted">{j.reason||t('No inferred cause')}</span></div><p class="path-line">{#each j.steps??[] as step,i}{#if i>0} {step.gapBefore?' ⋯ [window gap] ⋯ ':' → '}{/if}{step.step}{/each}</p>{#if j.windowFrom||j.windowTo}<p class="boundary-marker">║ {t('Evidence window')}: {dateTime(j.windowFrom)} → {dateTime(j.windowTo)}. {t('Window clipping does not create direct transitions.')}</p>{/if}{#if j.rightCensored}<p class="warning">{t('Right-censored at the selected window. Later evidence is outside this view; the captured boundary is preserved.')} {j.capturedStatus?`${t('Captured status')}: ${j.capturedStatus}`:''}</p>{/if}{#each j.warnings??[] as warning}<p class="warning">{t(warning)}</p>{/each}
          {#if selectedReference}<p class="boundary-marker">║ {t('Captured boundaries are preserved.')} {#if boundaryMissing(j)}{t('Boundary / unavailable endpoint')}. {/if} {j.partial?t('Partial beginning'):''}</p>{/if}
          {#if (j.timings??[]).length}<details class="nested-details"><summary>{t('Timing observations')}</summary><div class="table-wrap"><table><thead><tr><th>{t('Stage')}</th><th>{t('Timing basis')}</th><th>{t('Median')} / elapsed</th><th>{t("Quality")}</th></tr></thead><tbody>{#each j.timings as timing}<tr><td>{timing.stage}</td><td>{timing.basis}</td><td>{duration(timing.milliseconds,t('Unavailable'))}{timing.provisional?' · provisional':''}</td><td>{timing.quality}{!timing.complete?' · censored':''}</td></tr>{/each}</tbody></table></div></details>{/if}
          <details class="correlation-details"><summary>{t('Correlation details')}</summary><p class="mono">{j.scope}{j.tab?' / '+j.tab:''}</p></details><h3>{t('Ordered evidence')}</h3><ol class="sequence-list">{#each referenceEvidence(j).slice(0,pageLimits[j.id]??50) as e (e.id)}<li><div class="sequence-main"><span class="sequence-dot" class:friction={e.severity>=13||!!e.attrs?.['exception.type']}></span><div><strong>{e.name}</strong><small>{e.source} / {e.signal} · {e.service||'unknown service'}</small></div><span class="event-time">{dateTime(e.time)}</span></div><details class="event-details"><summary>{t('Evidence details')}</summary><dl><div><dt>{t('Occurrence time')}</dt><dd>{dateTime(e.time)}{e.fallback?' · receipt fallback':''}</dd></div><div><dt>{t('Receipt time')}</dt><dd>{dateTime(e.receipt)}</dd></div><div><dt>Occurrence nanos (exact)</dt><dd class="mono">{e.time}</dd></div><div><dt>{t("Receipt lag")}</dt><dd>{duration(receiptLagMilliseconds(e.receipt,e.time),t('Unavailable'))} · clocks may differ</dd></div><div><dt>{t("Record / action")}</dt><dd class="mono">{e.record||'identity unavailable'} / {e.action||'—'}</dd></div><div><dt>{t("Version / definition")}</dt><dd>{e.version||'unknown'} / v{e.definition}</dd></div></dl>{#if Object.keys(e.attrs??{}).length}<h4>{t('Safe diagnostic projection')}</h4><pre>{summaryText(e.attrs)}</pre>{/if}<button class="secondary" onclick={()=>copyEvidence(e)}>{copied===String(e.id)?t('Copied'):t('Copy sanitized context')}</button></details></li>{/each}</ol>{#if referenceEvidence(j).length>(pageLimits[j.id]??50)}<button class="secondary" onclick={()=>pageLimits[j.id]=(pageLimits[j.id]??50)+50}>{t('Load more evidence')} ({Math.min(pageLimits[j.id]??50,referenceEvidence(j).length)}/{referenceEvidence(j).length})</button>{/if}<p class="boundary-marker">║ Captured {j.status} boundary · {dateTime(j.end||j.lastMapped)}</p></div>
          </details>
        {/each}</section>
        <details class="panel"><summary>{t('Unassigned records')} · {model.unassigned?.length??0}</summary><p class="muted">{t("Standard telemetry is accepted without journey fields. Missing scope/tab, unmapped meaning or metrics receipt does not become a fabricated journey.")}</p><div class="table-wrap"><table><thead><tr><th>{t('Event')}</th><th>{t('Producer / signal')}</th><th>{t('Occurrence time')}</th><th>{t('Context')}</th></tr></thead><tbody>{#each (model.unassigned??[]).slice(0,200) as e}<tr><th scope="row">{e.name}</th><td>{e.source} / {e.signal}</td><td>{dateTime(e.time)}</td><td>{e.scope?'scope supplied':'no logical scope'}{e.source==='browser'&&!e.tab?' · no tab':''}</td></tr>{/each}</tbody></table></div></details>
        <details class="panel"><summary>Diagnostics · {model.diagnostics?.length??0}</summary><p class="muted">{t("Diagnostic records, qualified occurrences and affected visits are distinct. Shared stacks group similar failures; proximity does not establish cause. Free-text messages and stacks are omitted by the default privacy projection.")}</p><pre>{summaryText(model.diagnostics)}</pre></details>

        {:else if tool==='references'}      <section><p class="section-description">{t('Captured boundaries are preserved.')} Saved queries retain filters and definition context, never expired individual evidence. Choosing an investigation goal does not change the operational goal.</p>{#if !readOnly}<form class="panel view-form" onsubmit={e=>{e.preventDefault();void saveView()}}><h3>{t('Save a reference view')}</h3>{#if mode==='live'}<p class="inspector-note">{t('Saves this live observation window with fixed bounds. The seven-day baseline is a separate comparison layer.')}</p>{/if}<div class="form-grid"><label>{t('Name')}<input bind:value={viewName} required maxlength="100"/></label><label>{t('Mode')}<select bind:value={viewMode}><option value="overview">{t('Current workspace')}</option><option value="goal-backward">{t('Goal-backward')}</option><option value="segment">{t('Beginning / end segment')}</option><option value="origin-forward">{t('Origin-forward')}</option></select></label>{#if viewMode!=='goal-backward'&&viewMode!=='overview'}<label>{t('Beginning event')}<input bind:value={viewStart} list="view-events" required/></label><label>{t('Beginning occurrence')}<select bind:value={endpointStart}><option value="first">{t('First occurrence')}</option><option value="last">{t('Last occurrence')}</option></select></label>{/if}{#if viewMode!=='origin-forward'&&viewMode!=='overview'}<label>{t('End / goal event')}<input bind:value={viewEnd} list="view-events" required/></label><label>{t('End / goal occurrence')}<select bind:value={endpointEnd}><option value="first">{t('First occurrence')}</option><option value="last">{t('Last occurrence')}</option></select></label>{/if}</div><datalist id="view-events">{#each events as [name]}<option value={name}></option>{/each}</datalist><p class="muted">Current filters: {version||t('All versions')} · {definition?'v'+definition:t('All definitions')} · {from||'retained start'} → {to||'now'}</p><button disabled={busy}>{t('Save view')}</button></form>{/if}<div class="saved-grid">{#each (snapshot?.views??[]).filter(v=>v.mode!=='trace') as view}<article class="panel saved-view"><span class="eyebrow">{t(view.mode==='overview'?'Current workspace':view.mode==='goal-backward'?'Goal-backward':view.mode==='origin-forward'?'Origin-forward':'Beginning / end segment')}</span><h3>{view.name}</h3><p class="mono">{view.mode==='overview'?t('All captured paths'):(view.start||'…')+' → '+(view.end||'…')}</p><p class="muted">{view.definition?'v'+view.definition:t('All definitions')} · {view.version||t('All versions')}</p><div class="button-row"><button class="secondary" onclick={()=>openView(view)}>{t('Open view')} →</button>{#if !readOnly}<button class="quiet-button" disabled={busy} aria-label={t('Delete reference')+': '+view.name} onclick={()=>pendingReferenceDelete=view.id}>{t('Delete reference')}</button>{/if}</div>{#if !readOnly&&pendingReferenceDelete===view.id}<div class="confirm-box"><p><strong>{t('Delete reference')} “{view.name}”?</strong></p><p>{t('Only this saved view is removed. Collected events, journeys and other references are kept.')}</p><div class="button-row"><button class="danger" disabled={busy} onclick={()=>deleteReference(view)}>{t('Delete')}</button><button class="secondary" disabled={busy} onclick={()=>pendingReferenceDelete=null}>{t('Cancel')}</button></div></div>{/if}</article>{/each}{#if !snapshot?.views?.length}<p class="empty-state">{t('No saved views')}</p>{/if}</div></section>

        {:else if tool==='lifecycle'}      <section><div class="lifecycle-grid"><article class="panel"><span class="large-number">30 <small>{t("days")}</small></span><h3>{t("Ordered detail")}</h3><p>{t("Detailed evidence expires by occurrence time; supported first-receipt fallback is labeled. Reads exclude expired evidence immediately. Known replays do not extend its lifetime.")}</p><p>{t('Journey summaries finalize at captured start plus 30 days. Later corrections cannot revise a finalized summary from expired individual detail.')}</p></article><article class="panel"><span class="large-number">12 <small>{t("months")}</small></span><h3>{t('Retained summaries')}</h3><p>Supported daily counts, conversion denominators and timing distributions. {t('No individual drilldown after detail expiry.')} Combined medians are not averaged.</p></article></div><details class="panel" open><summary>{t('Retained summaries')}</summary><p class="muted">{t("Summary support is limited to declared app/day/version/definition/timing dimensions. Summary-only periods do not reconstruct paths. Approximate histogram quantiles differ from exact retained-detail samples.")}</p><p class="reading-note">{t('Finalized summaries are app-wide and use whole UTC days. Individual visit scope is unsupported after detail expiry; select all app traffic and whole-day bounds to query summaries.')}</p><div class="table-wrap"><table><caption>Selected retained summary period · {snapshot?.summary?.length??0} UTC days. Groups preserve their captured definition and initial version.</caption><thead><tr><th>Definition / version</th><th>Records</th><th>Eligible journeys</th><th>{t('Completed goals')}</th><th>Observed conversion</th><th>{t('Inactive')} / {t('Exited')}</th></tr></thead><tbody>{#each summaryGroups as g}<tr><th scope="row">{g.key}</th><td>{g.records}</td><td>{g.journeys}</td><td>{g.completed}</td><td>{pct(g.completed,g.journeys)}</td><td>{g.inactive} / {g.exits}</td></tr>{/each}</tbody></table></div>{#if !summaryGroups.length}<p class="empty-state">No finalized summaries in this range. Retained detail remains in the explorer; summaries finalize as their correction horizon expires.</p>{/if}{#each summaryGroups as g}{#if Object.keys(g.histograms).length||Object.keys(g.excluded).length}<h4>{g.key}</h4><div class="table-wrap"><table><thead><tr><th>{t('Stage')} / {t('Timing basis')}</th><th>{t('Completed samples / exclusions')}</th><th>Approximate median bin</th><th>Approximate p90 bin</th></tr></thead><tbody>{#each [...new Set([...Object.keys(g.histograms),...Object.keys(g.excluded)])] as stage}{@const h=g.histograms[stage]??{}}<tr><th scope="row">{stage}</th><td>{histogramSamples(h)} / {g.excluded[stage]??0}{!g.exclusionsAvailable?' + unknown':''}</td><td>{histogramQuantile(h,.5)??t('Unavailable')}</td><td>{histogramSamples(h)>=20?histogramQuantile(h,.9):t('Unavailable')}</td></tr>{/each}</tbody></table></div>{/if}{/each}<p class="muted footnote">Period distributions merge bucket counts (ratio 1.1). Bin ranges disclose precision; medians are never averaged. Exclusions retain censored or unavailable timing counts, separately from completed samples. Older summaries without exclusion coverage are marked unknown.</p></details><details class="panel"><summary>{t('Collection health')}</summary><p class="muted">{t("Explains data completeness, privacy filtering, view freshness and verified transport support. These are reported policies and known limitations, not a live guarantee that every event arrived.")}</p><pre>{summaryText(snapshot?.health)}</pre></details><details class="panel"><summary>{t('Limits')}</summary><p class="muted">{t("Caps how many records one view can process and return to keep the app responsive. If results are truncated, counts are partial; narrow your time range or filters. These caps do not change data retention.")}</p><pre>{summaryText(snapshot?.limits)}</pre></details>{#if !readOnly}<section class="panel deletion"><h3>{t("Deletion and correction limits")}</h3><p>{t("Identifiable visit deletion removes retained detail and supported contributions. After detail expiry, individual summary subtraction is unavailable; explicit app/time-bucket deletion is required. Inferred journey boundaries cannot guarantee journey-only replay protection. Client copies, filesystem snapshots and backups are outside server erasure guarantees.")}</p><div class="summary-deletion"><h4>{t('Delete one summary UTC day')}</h4><p>{t('This removes only the selected app-wide summary day. Retained detail, other days and intake are unchanged. It does not identify an individual contribution.')}</p><label>{t('Summary UTC day')}<input type="date" bind:value={summaryBucket}/></label><button class="secondary" disabled={!/^\d{4}-\d{2}-\d{2}$/.test(summaryBucket)} onclick={()=>{pendingDelete='bucket';deleteConfirm=''}}>{t('Delete summary day')}</button></div><label>{t('Visit scope')}<input bind:value={deleteScope} list="delete-scopes"/></label><datalist id="delete-scopes">{#each scopes as s}<option value={s}></option>{/each}</datalist><div class="button-row"><button class="secondary" disabled={!deleteScope} onclick={()=>{pendingDelete='visit';deleteConfirm=''}}>{t('Delete this visit')}</button><button class="danger" onclick={()=>{pendingDelete='app';deleteConfirm=''}}>{t('Delete app data and disable intake')}</button></div>{#if pendingDelete}<div class="confirm-box"><h4>{t('Confirmation')}</h4><p>Type <strong class="mono">{deletionConfirmation()}</strong> to confirm this explicit {pendingDelete==='bucket'?'summary UTC-day':pendingDelete} deletion.</p><label>{t('Confirmation')}<input bind:value={deleteConfirm} autocomplete="off"/></label><div class="button-row"><button class="danger" disabled={busy||deleteConfirm!==deletionConfirmation()} onclick={deleteData}>{t('Delete')}</button><button class="secondary" onclick={()=>pendingDelete=null}>{t('Cancel')}</button></div></div>{/if}</section>{/if}</section>

        {:else if tool==='discovery'}
          <p class="inspector-note">{t('Discovery uses retained app-wide evidence. Unconnected events have no supported journey relationship.')}</p><label class="toggle"><input type="checkbox" bind:checked={showDiscovery}/>{t('Show discovered events on canvas')}</label>
          <div class="discovery-list">{#each events.filter(([name])=>!active?.mappings.some(m=>m.event===name)) as [name,info]}<button class="neighbor-row" onclick={()=>{selectedStep='event:'+name;selectedEdge='';showDiscovery=true;tool=''}}><span>{name}<small>{[...info.sources].join(', ')}</small></span><small>{info.count} {t('records')}</small></button>{:else}<p class="muted">{t('No unmapped events')}</p>{/each}</div>
        {:else if tool==='configuration'&&!readOnly}
          <p class="inspector-note">{t('Active definition')} v{active?.version??'—'} · {t('Operational goal')}: <strong>{active?.goal??'—'}</strong></p>
          <div class="mapping-review">{#each active?.mappings??[] as mapping}<button class="neighbor-row" onclick={()=>openMapping(mapping.event)}><span>{mapping.event}<small>{mapping.source||t('Any source')} · {t(mapping.kind)}</small></span><span>{mapping.step} →</span></button>{/each}</div>
          <h3>{t('Set operational goal')}</h3><p class="inspector-note">{t('Exploring paths to a stage does not change the operational goal.')}</p><div class="goal-buttons">{#each active?.mappings??[] as mapping}<button class="chip" onclick={()=>openMapping(mapping.event,true)}>{mapping.event}{active?.goal===mapping.event?' ✓':''}</button>{/each}</div>
          <details><summary>{t('Timing policy')}</summary><form onsubmit={e=>{e.preventDefault();void activate()}}><label class="toggle"><input type="checkbox" bind:checked={draft.fallbackTiming}/>{t('Next-event estimated timing')}</label><button disabled={busy}>{t('Activate new definition')}</button></form></details>
        {:else}
          <p class="inspector-note">{t('Synthetic local data only. Standard reception does not require Sentrame fields. Correlation is not identity, authority or causality. Metrics are receipt-only. Home Server, shared Tunnel and real application integration remain unqualified.')}</p><p class="inspector-note">{t(model.policy)}</p>{#each model.warnings??[] as warning}<p class="warning">{t(warning)}</p>{/each}
        {/if}
      </Modal>
    {/if}
  {/if}
  <footer class:workspace-footer={authenticated}><span>sentrame · {t('The thread between events')}</span><span>30-day detail · 12-month supported summaries · {t('Local qualification only')}</span></footer>
</main>
